<template>
  <section class="robot-call-tree" aria-label="程序调用关系">
    <header class="call-tree-heading"><div><h3>程序调用</h3><p>{{ graph.statistics.tasks }} 个任务 · {{ graph.statistics.modules }} 个模块 · {{ graph.statistics.routines }} 个例程</p></div><div class="call-tree-tools"><el-input v-model="search" clearable aria-label="搜索程序调用" placeholder="搜索例程、模块或已保存说明" /><el-button size="small" @click="expandAll">全部展开</el-button><el-button size="small" @click="collapseAll">全部折叠</el-button></div></header>
    <p class="call-tree-note">按任务、模块查看调用，主要功能取自已保存分析。这里只显示已解析的静态关系，不代表完整执行顺序。</p>
    <div v-if="graph.tasks.length" class="call-tree-layout">
      <nav class="program-hierarchy" aria-label="任务与模块调用树">
        <section v-for="task in filtered" :key="task.id" class="call-task">
          <button class="hierarchy-toggle task-toggle" type="button" :aria-expanded="isTaskOpen(task.id)" @click="toggleTask(task.id)"><span class="chevron">{{ isTaskOpen(task.id)?'▾':'▸' }}</span><strong>{{ task.name }}</strong><small>{{ task.modules.length }} 个模块</small></button>
          <template v-if="isTaskOpen(task.id)"><section v-for="module in task.modules" :key="module.id" class="call-module"><button class="hierarchy-toggle module-toggle" type="button" :aria-expanded="isModuleOpen(module.id)" @click="toggleModule(module.id)"><span class="chevron">{{ isModuleOpen(module.id)?'▾':'▸' }}</span><span>{{ module.name }}</span><small>{{ module.readable?module.routineIds.length+' 个例程':'不可读' }}</small></button>
            <template v-if="isModuleOpen(module.id)"><p v-if="!module.readable" class="module-unavailable">{{ module.reason || '此模块不可读，未推断内部调用' }}</p><p v-else-if="!module.routineIds.length" class="module-unavailable">尚未解析到例程</p><div v-for="id in visibleRoutineIds(module)" :key="id" class="routine-tree-row" :class="{selected:selectedNode?.id===id}"><button type="button" class="routine-select" :aria-pressed="selectedNode?.id===id" @click="selectRoutine(id)"><span class="routine-kind">{{ graph.byId.get(id).kind }}</span><strong>{{ graph.byId.get(id).name }}</strong><small>{{ graph.byId.get(id).description.text }}</small></button><button type="button" class="routine-source" :aria-label="'定位 '+graph.byId.get(id).name+' 源码'" @click="locate(graph.byId.get(id).ref)">源码</button></div><button v-if="module.routineIds.length>routineLimit(module.id)" type="button" class="show-more" @click="showMore(module.id)">再显示 100 个例程（共 {{ module.routineIds.length }} 个）</button></template>
          </section></template>
        </section>
        <p v-if="!filtered.length" class="call-empty">未找到匹配的任务、模块或例程</p>
      </nav>
      <article v-if="selectedNode" class="routine-relations" aria-label="当前例程调用关系">
        <header class="routine-heading"><div><span>{{ selectedNode.taskName }} / {{ selectedNode.moduleName }}</span><h4>{{ selectedNode.kind }} {{ selectedNode.name }}</h4><small>{{ selectedNode.startLine }}–{{ selectedNode.endLine }} 行<span v-if="selectedNode.local"> · 模块内部例程</span></small></div><el-button size="small" @click="locate(selectedNode.ref)">定位源码</el-button></header>
        <section class="routine-purpose"><h5>主要功能 <small>{{ descriptionLabel(selectedNode.description) }}</small></h5><p>{{ selectedNode.description.text }}</p><div v-if="selectedNode.description.refs.length" class="call-evidence"><button v-for="ref in selectedNode.description.refs" :key="ref.fileId+':'+ref.startLine+':'+ref.endLine" type="button" @click="locate(ref)">说明依据 {{ ref.startLine }}–{{ ref.endLine }} 行</button></div></section>
        <section class="relation-group"><h5>调用了什么 <span>{{ resolvedCallGroups.length }} 个例程 · {{ resolvedCalls.length }} 次调用</span></h5><p v-if="!resolvedCalls.length" class="call-empty">尚未解析到确定的程序例程调用</p><article v-for="call in resolvedCallGroups" :key="call.id" class="call-edge"><header><button type="button" class="call-target" @click="locate(graph.byId.get(call.targetId).ref)">{{ qualifiedName(graph.byId.get(call.targetId)) }}</button><span class="call-status">{{ callStatus(call) }}</span></header><details v-if="call.count>1" class="call-site-list"><summary>全部 {{ call.count }} 处调用位置</summary><button v-for="(site,index) in call.sites" :key="index" type="button" @click="locate(site.ref)">{{ site.line }} 行</button></details><p v-if="call.cyclic" class="cycle-note">{{ call.recursive?'自调用':'循环引用' }}：使用定位或查看关系，不重复展开。</p><div class="call-edge-actions"><button type="button" @click="locate(call.ref)">调用位置 · {{ call.line }} 行</button><button type="button" @click="selectRoutine(call.targetId)">查看此例程关系</button></div></article><details v-if="unresolvedCalls.length" class="unresolved-call-group"><summary>指令、动态与待核调用 · {{ unresolvedCalls.length }}</summary><article v-for="call in unresolvedCallGroups" :key="call.id" class="call-edge" :class="call.status"><header><strong>{{ call.name }}</strong><span class="call-status">{{ callStatus(call) }}</span></header><p>{{ call.reason }}</p><details v-if="call.count>1" class="call-site-list"><summary>全部 {{ call.count }} 处调用位置</summary><button v-for="(site,index) in call.sites" :key="index" type="button" @click="locate(site.ref)">{{ site.line }} 行</button></details><div class="call-edge-actions"><button type="button" @click="locate(call.ref)">调用位置 · {{ call.line }} 行</button></div><details v-if="call.candidateIds.length" class="ambiguous-candidates"><summary>候选定义（不代表已确认调用）</summary><button v-for="id in call.candidateIds" :key="id" type="button" @click="locate(graph.byId.get(id).ref)">{{ qualifiedName(graph.byId.get(id)) }} · {{ graph.byId.get(id).startLine }} 行</button></details></article></details></section>
        <section class="relation-group"><h5>被谁调用 <span>{{ selectedNode.calledBy.length }}</span></h5><p v-if="!selectedNode.calledBy.length" class="call-empty">备份中未解析到确定调用方；可能是主入口、事件入口或外部调用。</p><article v-for="(caller,index) in callerGroups" :key="caller.sourceId+':'+caller.line+':'+index" class="call-edge"><header><button type="button" class="call-target" @click="locate(caller.ref)">{{ qualifiedName(graph.byId.get(caller.sourceId)) }}</button><span v-if="caller.cyclic" class="call-status">循环引用</span></header><details v-if="caller.count>1" class="call-site-list"><summary>全部 {{ caller.count }} 处调用位置</summary><button v-for="(site,index) in caller.sites" :key="index" type="button" @click="locate(site.ref)">{{ site.line }} 行</button></details><div class="call-edge-actions"><button type="button" @click="locate(caller.ref)">调用位置 · {{ caller.line }} 行</button><button type="button" @click="selectRoutine(caller.sourceId)">查看调用方关系</button></div></article></section>
      </article>
      <div v-else class="call-empty relation-placeholder">选择一个例程，查看主要功能、调用对象和调用方</div>
    </div>
    <el-empty v-else description="此备份尚无可展示的程序模块" />
  </section>
</template>

<script setup>
import { computed, ref, watch } from 'vue'
import { buildRobotCallTree, filterRobotCallTree, robotRoutineReference, groupRobotCallSites } from '../utils/robot-call-tree.mjs'

const props=defineProps({files:{type:Array,default:()=>[]},selectedFileId:{type:[String,Number],default:''},annotations:{type:Array,default:()=>[]},overview:{type:Object,default:null},analysis:{type:Object,default:null},reports:{type:Object,default:()=>({})},sourceHash:{type:String,default:''}})
const emit=defineEmits(['locate']),search=ref(''),selectedId=ref(''),openTasks=ref(new Set()),openModules=ref(new Set()),limits=ref({})
const graph=computed(()=>buildRobotCallTree(props.files,{annotations:props.annotations,overview:props.overview,analysis:props.analysis,reports:props.reports,sourceHash:props.sourceHash}))
const filtered=computed(()=>filterRobotCallTree(graph.value,search.value)),selectedNode=computed(()=>graph.value.byId.get(selectedId.value)||null)
const resolvedCalls=computed(()=>selectedNode.value?.calls.filter(call=>call.status==='resolved')||[]),unresolvedCalls=computed(()=>selectedNode.value?.calls.filter(call=>call.status!=='resolved')||[])
const resolvedCallGroups=computed(()=>groupRobotCallSites(resolvedCalls.value)),unresolvedCallGroups=computed(()=>groupRobotCallSites(unresolvedCalls.value)),callerGroups=computed(()=>groupRobotCallSites(selectedNode.value?.calledBy||[],true))
function revealNode(node){if(!node)return;openTasks.value=new Set([...openTasks.value,node.taskId]);openModules.value=new Set([...openModules.value,node.moduleId])}
watch(graph,()=>{if(!graph.value.byId.has(selectedId.value)){const node=graph.value.nodes.find(node=>String(node.fileId)===String(props.selectedFileId))||graph.value.nodes[0];selectedId.value=node?.id||'';revealNode(node)}},{immediate:true})
watch(()=>props.selectedFileId,()=>{const node=graph.value.nodes.find(node=>String(node.fileId)===String(props.selectedFileId));if(node)selectRoutine(node.id)})
watch([search,graph],()=>{if(!search.value.trim())return;openTasks.value=new Set(filtered.value.map(task=>task.id));openModules.value=new Set(filtered.value.flatMap(task=>task.modules.map(module=>module.id)))})
function selectRoutine(id){const node=graph.value.byId.get(id);if(!node)return;selectedId.value=id;revealNode(node)}
function isTaskOpen(id){return openTasks.value.has(id)}
function isModuleOpen(id){return openModules.value.has(id)}
function toggleTask(id){const next=new Set(openTasks.value);next.has(id)?next.delete(id):next.add(id);openTasks.value=next}
function toggleModule(id){const next=new Set(openModules.value);next.has(id)?next.delete(id):next.add(id);openModules.value=next}
function expandAll(){openTasks.value=new Set(graph.value.tasks.map(task=>task.id));openModules.value=new Set(graph.value.tasks.flatMap(task=>task.modules.map(module=>module.id)))}
function collapseAll(){openTasks.value=new Set();openModules.value=new Set()}
function routineLimit(id){return limits.value[id]||100}
function visibleRoutineIds(module){return module.routineIds.slice(0,routineLimit(module.id))}
function showMore(id){limits.value={...limits.value,[id]:routineLimit(id)+100}}
function locate(ref){const target=robotRoutineReference(ref);if(target)emit('locate',target)}
function qualifiedName(node){return node?node.moduleName+' / '+node.name:'未解析例程'}
function callStatus(call){return call.status==='resolved'?(call.cyclic?'循环引用':'已定位定义'):call.status==='ambiguous'?'同名待核':call.status==='dynamic'?'动态调用':'外部 / 未解析'}
function descriptionLabel(description){return description.source==='none'?'未生成说明':description.source==='annotation'?'部分行内说明':description.partial?'部分已保存分析':'已保存分析'}
</script>

<style scoped>
.robot-call-tree{min-width:0;color:var(--text,#283b50);font-size:13px;line-height:1.7;padding:16px 18px 24px}
.call-tree-heading,.call-tree-tools,.routine-heading,.call-edge>header{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}
.call-tree-heading h3{font-size:17px;margin:0}.call-tree-heading p{font-size:12px;color:var(--muted,#718194);margin:5px 0 0}.call-tree-tools{justify-content:flex-start;gap:8px}.call-tree-tools>.el-input{width:245px}.call-tree-tools .el-button+.el-button{margin:0}
.call-tree-note{color:var(--muted,#718194);font-size:12px;line-height:1.9;margin:15px 0 20px}.call-tree-layout{display:grid;grid-template-columns:minmax(190px,.75fr) minmax(0,1.25fr);gap:20px;align-items:start}
.program-hierarchy{border:1px solid var(--line,#dfe7ee);border-radius:8px;background:var(--card,#fff);overflow:hidden;min-width:0}
.call-task+.call-task{border-top:1px solid var(--line,#dfe7ee)}.hierarchy-toggle{display:flex;align-items:center;gap:8px;width:100%;padding:12px;border:0;background:transparent;color:inherit;text-align:left;cursor:pointer;font:inherit;line-height:1.65;min-width:0}
.hierarchy-toggle>strong,.hierarchy-toggle>span:not(.chevron){min-width:0;overflow-wrap:anywhere}.hierarchy-toggle>small{font-size:11px;color:var(--muted,#718194);margin-left:auto;flex:none}.task-toggle{background:var(--canvas,#f4f7fa)}.chevron{color:var(--muted,#718194);width:10px;flex:none}.call-module{border-top:1px solid var(--line,#dfe7ee)}.module-toggle{padding-left:22px}
.routine-tree-row{display:flex;align-items:center;min-width:0;padding:2px 8px 2px 28px;border-left:3px solid transparent}.routine-tree-row.selected{background:var(--brand-soft,#edf8f7);border-left-color:var(--brand,#087f78)}.routine-select{display:block;flex:1;min-width:0;text-align:left;font:inherit;color:inherit;border:0;background:transparent;padding:10px 0;cursor:pointer}.routine-select>strong{font-size:13px;overflow-wrap:anywhere}.routine-kind{font-family:Consolas,monospace;font-size:10px;color:var(--muted,#718194);margin-right:7px}.routine-select>small{display:block;color:var(--muted,#718194);font-size:11px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:100%;margin-top:3px}.routine-source{flex:none;font-size:11px;color:var(--brand,#087f78);background:transparent;border:0;cursor:pointer;padding:8px;margin-left:6px}
.module-unavailable,.call-empty{font-size:12px;color:var(--muted,#718194);line-height:1.9;margin:12px 14px;overflow-wrap:anywhere}.show-more{display:block;width:calc(100% - 36px);margin:5px 10px 12px 26px;text-align:left;font-size:11px;color:var(--brand,#087f78);background:transparent;border:0;cursor:pointer;padding:8px}
.routine-relations{min-width:0}.routine-heading{align-items:flex-start;border-bottom:1px solid var(--line,#dfe7ee);padding-bottom:15px}.routine-heading h4{font:600 18px/1.6 Consolas,monospace;margin:6px 0;overflow-wrap:anywhere}.routine-heading span,.routine-heading small{font-size:12px;color:var(--muted,#718194);overflow-wrap:anywhere}.routine-heading>div{min-width:0}.routine-purpose{background:var(--brand-soft,#edf8f7);border:1px solid var(--line,#dfe7ee);border-radius:8px;margin:18px 0;padding:15px}.routine-purpose h5,.relation-group h5{font-size:13px;margin:0 0 10px;font-weight:600}.routine-purpose h5 small{font-size:11px;font-weight:400;color:var(--muted,#718194);margin-left:5px}.routine-purpose p{margin:0;white-space:pre-wrap;overflow-wrap:anywhere;font-size:13px;line-height:1.9}.call-evidence{display:flex;gap:8px;flex-wrap:wrap;margin-top:10px}.call-evidence button,.call-edge-actions>button{color:var(--brand,#087f78);font-size:11px;border:0;background:transparent;cursor:pointer;padding:3px 0;text-align:left}
.unresolved-call-group{margin-top:16px;color:var(--muted,#718194);font-size:12px}.unresolved-call-group>summary{cursor:pointer;padding:9px 0}.relation-group{margin-top:24px}.relation-group h5>span{font-size:11px;font-weight:400;color:var(--muted,#718194);margin-left:6px}.relation-group>.call-empty{margin-left:0}.call-edge{border:1px solid var(--line,#dfe7ee);border-radius:7px;padding:12px;margin:10px 0;background:var(--card,#fff);min-width:0}.call-edge>header{align-items:flex-start;gap:8px}.call-target{font:600 12px/1.8 Consolas,monospace;text-align:left;color:var(--brand,#087f78);border:0;background:transparent;padding:0;cursor:pointer;overflow-wrap:anywhere;min-width:0;max-width:100%}.call-edge strong{font:600 12px/1.8 Consolas,monospace;overflow-wrap:anywhere;min-width:0}.call-status{font-size:10px;color:var(--muted,#718194);background:var(--canvas,#f4f7fa);border-radius:4px;padding:2px 5px;white-space:nowrap}.call-edge p{font-size:11px;color:var(--muted,#718194);line-height:1.9;margin:8px 0;overflow-wrap:anywhere}.call-edge.ambiguous .call-status,.call-edge.dynamic .call-status{color:var(--warning,#a86a1c)}.call-edge-actions{display:flex;gap:14px;flex-wrap:wrap;margin-top:8px}.ambiguous-candidates{font-size:11px;line-height:1.9;margin-top:10px;color:var(--muted,#718194)}.ambiguous-candidates summary{cursor:pointer}.ambiguous-candidates button{display:block;font-size:11px;color:var(--brand,#087f78);text-align:left;border:0;background:transparent;padding:5px 0;overflow-wrap:anywhere;cursor:pointer}.relation-placeholder{padding:40px 15px;margin:0;text-align:center}.robot-call-tree button:focus-visible,.robot-call-tree summary:focus-visible{outline:2px solid var(--brand,#087f78);outline-offset:3px}
@media(max-width:900px){.call-tree-layout{grid-template-columns:1fr}.robot-call-tree{padding:14px}.call-tree-tools{width:100%}.call-tree-tools>.el-input{flex:1;min-width:150px}.routine-select>small{white-space:normal;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical}.routine-heading h4{font-size:17px}.routine-relations{border-top:1px solid var(--line,#dfe7ee);padding-top:16px}.call-tree-note{margin-bottom:16px}}
@media(max-width:380px){.call-tree-tools>.el-input{width:100%;flex-basis:100%}.hierarchy-toggle{gap:5px;padding-left:10px}.module-toggle{padding-left:16px}.routine-tree-row{padding-left:20px}.call-tree-heading h3{font-size:16px}.call-edge{padding:10px}.routine-purpose{padding:12px}}
.call-site-list{margin-top:8px;font-size:11px;color:var(--muted,#718194)}.call-site-list summary{cursor:pointer}.call-site-list button{padding:4px 8px;margin:5px 5px 0 0;border:1px solid var(--line,#dfe7ee);border-radius:4px;background:transparent;color:var(--brand,#087f78);font:inherit;cursor:pointer}
</style>
